using System.Collections.Generic;
using System.Linq;
using Rapadura.Core.Localization;

namespace Rapadura.Gameplay.Quests
{
    /// <summary>
    /// Localization entries for the region side quests and their quest-givers (<see cref="RegionQuestCatalog"/>,
    /// <c>RegionNpcDialogues</c>): <c>quest.region_*</c> (title, description, objectives, journal),
    /// <c>dialogue.&lt;npc&gt;.*</c> for the four region NPCs, <c>dialogue.region_npc.*</c> (shared choice labels)
    /// and the world-map "Conversar com..." button (<c>ui.worldmap.talk*</c>). Same pattern as
    /// <c>QuestGiverTexts</c>/<c>DailyQuestTexts</c>: merged at runtime by <see cref="EnsureLoaded"/> (only keys
    /// not yet registered), by <c>DialogueManager</c>, <c>QuestLogDataSource</c> and the map talk button.
    /// </summary>
    public static class RegionQuestTexts
    {
        public const string TalkButtonKey = "ui.worldmap.talk";
        public const string TalkButtonNewsKey = "ui.worldmap.talk_news";

        public static readonly List<LocalizationEntry> All = new List<LocalizationEntry>
        {
            // -- World map button --
            new LocalizationEntry(TalkButtonKey, "Talk to {0}", "Conversar com {0}"),
            new LocalizationEntry(TalkButtonNewsKey, "Talk to {0} (!)", "Conversar com {0} (!)"),

            // -- Shared choice labels --
            new LocalizationEntry("dialogue.region_npc.choice_accept", "Leave it to us!", "Pode deixar com a gente!"),
            new LocalizationEntry("dialogue.region_npc.choice_decline", "Not now, I'll come back later.", "Agora não, depois eu volto."),
            new LocalizationEntry("dialogue.region_npc.choice_progress", "About that favor...", "Sobre aquele pedido..."),
            new LocalizationEntry("dialogue.region_npc.choice_news", "Any news around here?", "Alguma novidade por aqui?"),
            new LocalizationEntry("dialogue.region_npc.choice_boss", "What do you know about the boss around here?", "O que você sabe sobre o chefe daqui?"),
            new LocalizationEntry("dialogue.region_npc.choice_cleared", "The boss around here is down!", "O chefe daqui caiu!"),
            new LocalizationEntry("dialogue.region_npc.choice_goodbye", "See you!", "Até mais!"),

            // ================= Floresta (Bosque do Zarafshan) — Mariam, a Ervateira =================
            new LocalizationEntry("quest.region_forest_howling_trail.title", "Howls on the Trail", "Uivos na Trilha"),
            new LocalizationEntry("quest.region_forest_howling_trail.description", "The tugai wolves lost their fear and prowl the creek trail. Mariam, the herbalist at the edge of the Zarafshan Woods, asked the family for help.", "Os lobos do tugai perderam o medo e rondam a trilha do riacho. Mariam, a ervateira da beira do Bosque do Zarafshan, pediu ajuda à família."),
            new LocalizationEntry("quest.region_forest_howling_trail.obj_hunt_scrub_wolves", "Drive off tugai wolves", "Espantar lobos do tugai"),
            new LocalizationEntry("quest.region_forest_howling_trail.journal", "Mariam knew our grandparents. She says wolves smell fear, so we walk with our heads up — all five of us.", "A Mariam conheceu nossos avós. Ela diz que lobo fareja medo, então a gente anda de cabeça erguida — os cinco."),
            new LocalizationEntry("quest.region_forest_spider_webs.title", "Webs in the Herb Garden", "Teias na Horta de Ervas"),
            new LocalizationEntry("quest.region_forest_spider_webs.description", "Dimmed weaver spiders have webbed over Mariam's herb garden. No herbs means no tea and no medicine for anyone.", "Aranhas-tecelãs apagadas teceram teias na horta de ervas da Mariam. Sem erva, não tem chá nem remédio pra ninguém."),
            new LocalizationEntry("quest.region_forest_spider_webs.obj_clear_forest_spiders", "Defeat dimmed weaver spiders", "Derrotar aranhas-tecelãs apagadas"),
            new LocalizationEntry("quest.region_forest_spider_webs.journal", "Mariam's rule: whoever gets caught in a web calls their cousins. That's what family's for.", "Regra da Mariam: quem enrosca na teia chama os primos. Família é pra isso."),

            new LocalizationEntry("dialogue.forest_rezadeira.name", "Mariam the Herbalist", "Mariam, a Ervateira"),
            new LocalizationEntry("dialogue.forest_rezadeira.short_name", "Mariam", "Mariam"),
            new LocalizationEntry("dialogue.forest_rezadeira.greet_maithe", "Maithe, dear! The eldest of the bunch, bow on your back and an eye on everyone. Sit a while — even protectors need a cup of mint tea.", "Maithe, querida! A mais velha da turma, de arco nas costas e olho em todo mundo. Senta um pouco, que até protetora precisa de um chá de hortelã."),
            new LocalizationEntry("dialogue.forest_rezadeira.greet_maria", "Maria, light of the Sun Temple! Your grandma Edna used to pick herbs with me under this very apricot tree. You calm people down just the way she does, you know?", "Maria, luz do Templo Solar! A sua avó Edna colhia ervas comigo debaixo deste mesmo damasqueiro. Você acalma a gente do mesmo jeitinho dela, sabia?"),
            new LocalizationEntry("dialogue.forest_rezadeira.greet_joaquim", "Joaquim, shield up as always. Fair warning: nobody here needs a wall, just someone to eat my apricot cake.", "Joaquim, de escudo em punho, como sempre. Já vou avisando: aqui ninguém precisa de muralha, só de alguém que coma meu bolo de damasco."),
            new LocalizationEntry("dialogue.forest_rezadeira.greet_icaro", "Ícaro! If that drone of yours scares my hens again, no dried apricots for you. ...Fine, have one.", "Ícaro! Se esse seu drone espantar minhas galinhas de novo, você fica sem damasco seco. ...Tá bom, pega um."),
            new LocalizationEntry("dialogue.forest_rezadeira.greet_lavine", "Look at the youngest! So small and already walking the woods on her own... Don't make that face, Lavine, I know you can handle it.", "Olha só a caçula! Pequenininha e já andando sozinha pelo bosque... Não faz essa cara, Lavine, eu sei que você dá conta."),
            new LocalizationEntry("dialogue.forest_rezadeira.greet_any", "Another one of the family! The woods are restless, dear. Sit down and I'll tell you.", "Chegou mais um da família! O bosque anda agitado, meu bem. Senta, que eu te conto."),
            new LocalizationEntry("dialogue.forest_rezadeira.menu", "Anything else, dear?", "Mais alguma coisa, meu bem?"),
            new LocalizationEntry("dialogue.forest_rezadeira.choice_q1", "What's all that howling on the trail?", "Que uivos são esses na trilha?"),
            new LocalizationEntry("dialogue.forest_rezadeira.q1_offer", "The tugai wolves lost their fear and are prowling the creek trail. Nobody dares fetch water anymore. Will you drive off five of them? I'll give you some potions I brewed myself.", "Os lobos do tugai perderam o medo e estão rondando a trilha do riacho. Ninguém mais vai buscar água. Espanta cinco deles pra mim? Te dou umas poções que eu mesma preparei."),
            new LocalizationEntry("dialogue.forest_rezadeira.choice_accept_special", "Leave it to me! I'm not a little kid anymore.", "Deixa comigo! Eu não sou mais criança."),
            new LocalizationEntry("dialogue.forest_rezadeira.q1_accepted", "Go with light. And remember: wolves smell fear, so walk with your head up, like your whole family does.", "Vai com luz. E lembra: lobo fareja medo, então anda de cabeça erguida, igual à sua família inteira."),
            new LocalizationEntry("dialogue.forest_rezadeira.q1_active", "I still hear howling by the creek. Five wolves, dear, then come back for some tea.", "Ainda escuto uivo perto do riacho. Cinco lobos, meu bem, e depois volta pra tomar um chá."),
            new LocalizationEntry("dialogue.forest_rezadeira.choice_q2", "Need any more help, Aunt Mariam?", "Precisa de mais ajuda, tia Mariam?"),
            new LocalizationEntry("dialogue.forest_rezadeira.q2_offer", "The trail is quiet again, thank you! But now the weaver spiders have webbed over my herb garden. No herbs means no tea and no medicine for anyone's family. Will you take down four of them?", "A trilha está quieta de novo, obrigada! Mas agora as aranhas-tecelãs teceram teia na minha horta de ervas. Sem erva, não tem chá nem remédio pra família de ninguém. Derruba quatro delas?"),
            new LocalizationEntry("dialogue.forest_rezadeira.q2_accepted", "Watch out for the sticky webs — whoever gets tangled calls their cousins. That's what family's for.", "Cuidado com a teia grudenta: quem enrosca chama os primos. Família é pra isso."),
            new LocalizationEntry("dialogue.forest_rezadeira.q2_active", "Four spiders, dear. They hide where the shade is coldest. Poor things, they've forgotten they used to weave for the woods.", "Quatro aranhas, meu bem. Elas se escondem onde a sombra é mais fria. Coitadas, esqueceram que já teceram pro bosque."),
            new LocalizationEntry("dialogue.forest_rezadeira.all_done", "The herb garden is green again. Every time I brew tea I'll think of you five. Give your cousins a hug from me!", "A horta está verdinha de novo. Toda vez que eu fizer chá, vou lembrar de vocês cinco. Manda um abraço pros primos!"),
            new LocalizationEntry("dialogue.forest_rezadeira.declined", "No rush. The woods will wait, and so will the tea.", "Sem pressa. O bosque espera, e o chá também."),
            new LocalizationEntry("dialogue.forest_rezadeira.boss", "If you're facing Kök-Böri, the Sky Wolf, listen to this old woman: he never attacks alone at first. Let the pack come, drop the small ones, and only then face the big one. He used to guide travellers through the tugai, you know. The shadow made him forget.", "Se vai enfrentar Kök-Böri, o Lobo Celeste, escuta esta velha: ele nunca ataca sozinho no começo. Deixa a matilha chegar, derruba os pequenos, e só então encara o grandão. Ele guiava os viajantes no tugai, sabia? A sombra fez ele esquecer."),
            new LocalizationEntry("dialogue.forest_rezadeira.boss_special", "Maithe, you're the family's huntress, so you'll get this: Kök-Böri charges in a straight line when he's angry. Keep your distance, aim steady and don't let him corner you. Your cousins are counting on you.", "Maithe, você é a caçadora da família, então vai entender: o Kök-Böri avança em linha reta quando fica bravo. Mantém distância, mira firme e não deixa ele te encurralar. Seus primos contam com você."),
            new LocalizationEntry("dialogue.forest_rezadeira.cleared", "Kök-Böri is down? Then his spark went up and the woods sleep in peace tonight! I made halva to celebrate — take some to your cousins, okay?", "O Kök-Böri caiu? Então a faísca dele subiu e hoje o bosque dorme em paz! Fiz halva pra comemorar — leva pros primos, viu?"),

            // -- forest_rezadeira after the boss (greet_after_*, RegionNpcDialogues: region cleared) --
            new LocalizationEntry("dialogue.forest_rezadeira.greet_after_maithe", "Maithe! Since Kök-Böri remembered who he was, the pack walks past here with their tails down. Sit — today the tea is on me. And tell your cousins on the radio, alright?", "Maithe! Desde que o Kök-Böri lembrou quem era, a matilha passa aqui de rabo baixo. Senta, que hoje o chá é por minha conta. E conta pros primos pelo rádio, viu?"),
            new LocalizationEntry("dialogue.forest_rezadeira.greet_after_maria", "Maria, my flower! The wolves are just wolves again. You were the one who said someone had put out his light, weren't you? Well, the woods are lit again.", "Maria, minha flor! Os lobos voltaram a ser só lobos. Foi você que disse que alguém tinha apagado a luz dele, né? Pois o bosque acendeu de novo."),
            new LocalizationEntry("dialogue.forest_rezadeira.greet_after_joaquim", "Joaquim! The whole forest sleeps in peace since you helped Kök-Böri. They say he's back to guiding travellers. Now you can lower that shield and eat a slice of cake, boy.", "Joaquim! O bosque inteiro dorme em paz desde que vocês libertaram o Kök-Böri. Dizem que ele voltou a guiar os viajantes. Agora pode baixar esse escudo e comer um pedaço de bolo, menino."),
            new LocalizationEntry("dialogue.forest_rezadeira.greet_after_icaro", "Ícaro! I heard you found golden sand on Kök-Böri's trail. You've already put some in a jar to study, I bet.", "Ícaro! Contaram que vocês acharam areia dourada na trilha do Kök-Böri. Já guardou num potinho pra estudar, aposto."),
            new LocalizationEntry("dialogue.forest_rezadeira.greet_after_lavine", "Lavine, the youngest who helped free the Sky Wolf! I told you you could handle it. The woods are calm as can be now.", "Lavine, a caçula que ajudou a libertar o Lobo Celeste! Eu bem que disse que você dava conta. O bosque tá mansinho, mansinho."),
            new LocalizationEntry("dialogue.forest_rezadeira.greet_after_any", "The woods have been at peace since Kök-Böri's spark went up. Sit down, dear, the tea is hot.", "O bosque tá em paz desde que a faísca do Kök-Böri subiu. Senta, meu bem, que o chá tá quente."),

            // ================= Deserto (Areias Flamejantes) — Ammo, o Caravaneiro =================
            new LocalizationEntry("quest.region_desert_stinger_road.title", "Stingers on the Road", "Ferrões no Caminho"),
            new LocalizationEntry("quest.region_desert_stinger_road.description", "Scorpions nested on the road to the well and Ammo's caravan is stuck in the middle of the Flaming Sands.", "Escorpiões fizeram ninho no caminho do poço e a caravana do Ammo empacou no meio das Areias Flamejantes."),
            new LocalizationEntry("quest.region_desert_stinger_road.obj_chase_dune_scorpions", "Drive off Flaming Sands scorpions", "Afastar escorpiões das Areias Flamejantes"),
            new LocalizationEntry("quest.region_desert_stinger_road.journal", "Ammo says the sting comes from above and the sands don't forgive anyone who forgets to drink water. Noted, Ammo.", "O Ammo diz que o ferrão vem de cima e que as areias não perdoam quem esquece de beber água. Anotado, Ammo."),
            new LocalizationEntry("quest.region_desert_crossing_reserve.title", "Savings for the Crossing", "Reserva pra Travessia"),
            new LocalizationEntry("quest.region_desert_crossing_reserve.description", "Ammo won't let anyone in the family head for the mountains without gold saved up — or with scorpions still circling the caravan.", "O Ammo não deixa ninguém da família seguir pra serra sem uma reserva de ouro — nem com escorpião rondando a caravana."),
            new LocalizationEntry("quest.region_desert_crossing_reserve.obj_guard_the_caravan", "Guard the caravan from scorpions", "Proteger a caravana dos escorpiões"),
            new LocalizationEntry("quest.region_desert_crossing_reserve.obj_save_crossing_gold", "Save gold for the crossing", "Juntar ouro para a travessia"),
            new LocalizationEntry("quest.region_desert_crossing_reserve.journal", "Saved gold means peace on the road, says the caravaneer. He sounds just like our parents.", "Ouro guardado é sossego na estrada, diz o caravaneiro. Ele fala igualzinho aos nossos pais."),

            new LocalizationEntry("dialogue.desert_tropeiro.name", "Ammo the Caravaneer", "Ammo, o Caravaneiro"),
            new LocalizationEntry("dialogue.desert_tropeiro.short_name", "Ammo", "Ammo"),
            new LocalizationEntry("dialogue.desert_tropeiro.greet_maithe", "Maithe! The hunters of the sands talk about a girl who hits a scorpion at a hundred paces. Had to be the eldest cousin of that noisy family.", "Maithe! Os caçadores das areias falam de uma moça que acerta escorpião a cem passos. Só podia ser a prima mais velha daquela família barulhenta."),
            new LocalizationEntry("dialogue.desert_tropeiro.greet_maria", "Maria! The lamp you lit for my caravan still looks after us — not one of my camels has fallen ill since you cared for them at Grandma Edna's.", "Maria! A lâmpada que você acendeu pra minha caravana ainda cuida da gente — nenhum camelo meu adoeceu desde que você tratou deles lá na casa da Vó Edna."),
            new LocalizationEntry("dialogue.desert_tropeiro.greet_joaquim", "Joaquim, boy, get that shield out of the sun — it gets hot enough to fry an egg! Stubborn as your grandpa Jorge. We crossed a lot of caravan roads together, he and I. He'd love to see you like this.", "Joaquim, menino, tira esse escudo do sol, que ele esquenta até fritar ovo! Teimoso igual ao seu avô Jorge. A gente cruzou muita estrada de caravana junto, eu e ele. Ele ia adorar te ver assim."),
            new LocalizationEntry("dialogue.desert_tropeiro.greet_icaro", "Ícaro, the inventor! That compass you fixed for me at Grandma's never lost north again. Want a look at the Artificers' Ruins? There are old engines there that are right up your alley.", "Ícaro, o inventor! Aquela bússola que você me consertou lá na casa da Vó nunca mais errou o norte. Quer dar uma olhada nas Ruínas dos Artífices? Tem engenho velho lá que é a sua cara."),
            new LocalizationEntry("dialogue.desert_tropeiro.greet_lavine", "Lavine? The little one crossed the Flaming Sands? ...Sorry, sorry. The great Lavine crossed the Flaming Sands. Better?", "Lavine? A caçulinha atravessou as Areias Flamejantes? ...Desculpa, desculpa. A grande Lavine atravessou as Areias Flamejantes. Assim está melhor?"),
            new LocalizationEntry("dialogue.desert_tropeiro.greet_any", "Well, look who's here! Another one of the family reaching the sands. Drink some water first, talk later.", "Olha só quem chegou! Mais um da família nas areias. Bebe água primeiro, conversa depois."),
            new LocalizationEntry("dialogue.desert_tropeiro.menu", "Anything else before the sun fries us?", "Mais alguma coisa antes do sol fritar a gente?"),
            new LocalizationEntry("dialogue.desert_tropeiro.choice_q1", "What's holding the caravan back?", "O que está segurando a caravana?"),
            new LocalizationEntry("dialogue.desert_tropeiro.q1_offer", "Scorpions, that's what. They nested right on the road to the well and my camels won't budge. Clear five of them off the road and I'll pay you with the best I've got: travel potions.", "Escorpião, é isso. Fizeram ninho bem no caminho do poço e meus camelos empacaram. Afasta cinco deles da estrada e eu te pago com o que tenho de melhor: poção de viagem."),
            new LocalizationEntry("dialogue.desert_tropeiro.choice_accept_special", "Five scorpions? My drone will handle that before lunch!", "Cinco escorpiões? Meu drone resolve antes do almoço!"),
            new LocalizationEntry("dialogue.desert_tropeiro.q1_accepted", "Watch their tails — the sting comes from above. And drink water; the sands don't forgive the forgetful.", "Olho no rabo deles, que o ferrão vem de cima. E bebe água, que as areias não perdoam quem esquece."),
            new LocalizationEntry("dialogue.desert_tropeiro.q1_active", "The camels still won't move. There are scorpions left on the well road.", "Os camelos ainda não saem do lugar. Tem escorpião sobrando no caminho do poço."),
            new LocalizationEntry("dialogue.desert_tropeiro.choice_q2", "What now, Ammo?", "E agora, Ammo?"),
            new LocalizationEntry("dialogue.desert_tropeiro.q2_offer", "The road is open, thank you! Now listen to an old caravaneer: nobody crosses to the mountains without savings. Gather twelve gold for the crossing and chase three more scorpions away from the caravan. I won't see anyone from this family going without.", "A estrada abriu, obrigado! Agora escuta um velho caravaneiro: ninguém atravessa pra serra sem reserva. Junta doze de ouro pra travessia e espanta mais três escorpiões da caravana. Não quero ver ninguém dessa família passando aperto."),
            new LocalizationEntry("dialogue.desert_tropeiro.q2_accepted", "Saved gold means peace on the road. Your parents would be glad to know you're looking after each other.", "Ouro guardado é sossego na estrada. Seus pais iam gostar de saber que vocês estão se cuidando."),
            new LocalizationEntry("dialogue.desert_tropeiro.q2_active", "Twelve gold saved and three fewer scorpions. Gold shines in the sand — just keep your eyes open.", "Doze de ouro guardados e três escorpiões a menos. Ouro brilha na areia, é só prestar atenção."),
            new LocalizationEntry("dialogue.desert_tropeiro.all_done", "Savings set, caravan safe. When you reach the Kaggen Range, tell Master Mihr that Ammo says hello. And share your water!", "Reserva feita, caravana segura. Quando chegarem na Serra de Kaggen, digam ao Mestre Mihr que o Ammo mandou lembranças. E dividam a água!"),
            new LocalizationEntry("dialogue.desert_tropeiro.declined", "Fair enough. The sands teach patience.", "Tá certo. As areias ensinam paciência."),
            new LocalizationEntry("dialogue.desert_tropeiro.boss", "The Great Ushabti never sleeps and never tires. The Artificers built it to answer, and it still answers — just to the wrong voice. It's made of old stone: when its core glows, get out of the way. Strike after the glow, never before.", "O Grande Ushabti não dorme e não cansa. Os Artífices fizeram ele pra responder, e ele ainda responde — só que pra voz errada. Ele é de pedra velha: quando o núcleo dele brilhar, sai da frente. Bate depois do brilho, nunca antes."),
            new LocalizationEntry("dialogue.desert_tropeiro.boss_special", "Ícaro, you know engines better than I do. The Great Ushabti is an Artificers' engine: its core glows right before it strikes. Dodge, let it cool down, and hit it hard. Maithe would be proud.", "Ícaro, você entende de engenho melhor que eu. O Grande Ushabti é engenho dos Artífices: o núcleo brilha logo antes do golpe. Desvia, deixa ele esfriar e acerta em cheio. A Maithe ia ficar orgulhosa."),
            new LocalizationEntry("dialogue.desert_tropeiro.cleared", "The Great Ushabti fell! Its spark went up and even the camels grunted for joy. The road to the range is yours.", "O Grande Ushabti caiu! A faísca dele subiu e até os camelos roncaram de alegria. A estrada da serra é de vocês."),

            // -- desert_tropeiro after the boss (greet_after_*, RegionNpcDialogues: region cleared) --
            new LocalizationEntry("dialogue.desert_tropeiro.greet_after_maithe", "Maithe! Since the Great Ushabti fell, my caravan passes the old stones singing. Is your brother still out there reading that panel?", "Maithe! Desde que o Grande Ushabti caiu, minha caravana passa pelas pedras velhas cantando. O seu irmão ainda tá lá decifrando aquele painel?"),
            new LocalizationEntry("dialogue.desert_tropeiro.greet_after_maria", "Maria! The Great Ushabti finally gets to rest. My camels and I sleep soundly again.", "Maria! O Grande Ushabti finalmente descansou. Meus camelos e eu dormimos sossegados de novo."),
            new LocalizationEntry("dialogue.desert_tropeiro.greet_after_joaquim", "Joaquim! I heard the Great Ushabti hit your shield and you didn't even blink. Your grandpa Jorge would be laughing with pride. He'd have loved this.", "Joaquim! Ouvi dizer que o Grande Ushabti bateu no seu escudo e você nem piscou. O seu avô Jorge ia rir de orgulho. Ele ia adorar isso."),
            new LocalizationEntry("dialogue.desert_tropeiro.greet_after_icaro", "Ícaro! The Great Ushabti fell and you still found a message from the Artificers in its gears? That's going to be a caravan story, lad.", "Ícaro! O Grande Ushabti caiu e você ainda achou recado dos Artífices nas engrenagens dele? Isso vai virar história de caravana, rapaz."),
            new LocalizationEntry("dialogue.desert_tropeiro.greet_after_lavine", "The great Lavine! Crossed the Flaming Sands and helped bring down the Great Ushabti. Nobody calls you the little one anymore, hear?", "A grande Lavine! Atravessou as Areias Flamejantes e ainda ajudou a derrubar o Grande Ushabti. Ninguém mais te chama de caçulinha, viu?"),
            new LocalizationEntry("dialogue.desert_tropeiro.greet_after_any", "The Great Ushabti is resting, and the road through the sands is yours. Have some water and stay for a chat.", "O Grande Ushabti descansou, e a estrada das areias é de vocês. Bebe uma água e fica pra conversa."),

            // ================= Montanha (Serra de Kaggen) — Mestre Mihr, o Mineiro =================
            new LocalizationEntry("quest.region_mountain_walking_stones.title", "Walking Stones", "Pedras que Andam"),
            new LocalizationEntry("quest.region_mountain_walking_stones.description", "Stone ushabtis come down the slope and crush the rails of Master Mihr's mine.", "Ushabtis de pedra descem a encosta e esmagam os trilhos da mina do Mestre Mihr."),
            new LocalizationEntry("quest.region_mountain_walking_stones.obj_topple_stone_golems", "Topple stone ushabtis", "Derrubar ushabtis de pedra"),
            new LocalizationEntry("quest.region_mountain_walking_stones.journal", "Master Mihr's tip: hit the joints, where stone cracks. And nobody charges ahead alone — that one was for Joaquim.", "Dica do Mestre Mihr: bater nas juntas, onde a pedra racha. E ninguém vai na frente sozinho — essa foi pro Joaquim."),
            new LocalizationEntry("quest.region_mountain_mine_pass.title", "The Mine Pass", "A Passagem da Mina"),
            new LocalizationEntry("quest.region_mountain_mine_pass.description", "The deep mine pass is overrun by stone ushabtis. Once it's clear, the mine bell will ring again after years of silence.", "A passagem funda da mina está tomada por ushabtis de pedra. Quando ela for liberada, o sino da mina volta a tocar depois de anos de silêncio."),
            new LocalizationEntry("quest.region_mountain_mine_pass.obj_open_the_mine_pass", "Clear the deep mine pass", "Liberar a passagem funda da mina"),
            new LocalizationEntry("quest.region_mountain_mine_pass.journal", "Master Mihr promised to tell his grandkids about the five cousins who made the mountain sing.", "O Mestre Mihr prometeu contar pros netos a história dos cinco primos que fizeram a serra cantar."),

            new LocalizationEntry("dialogue.mountain_miner.name", "Master Mihr the Miner", "Mestre Mihr, o Mineiro"),
            new LocalizationEntry("dialogue.mountain_miner.short_name", "Master Mihr", "Mestre Mihr"),
            new LocalizationEntry("dialogue.mountain_miner.greet_maithe", "Maithe! From up here I saw an arrow ride the wind across the whole valley and thought: that has to be the eldest of those cousins.", "Maithe! Lá de cima eu vi uma flecha atravessar o vale inteiro no vento e pensei: só pode ser a mais velha daqueles primos."),
            new LocalizationEntry("dialogue.mountain_miner.greet_maria", "Maria, good to see you. Up here the light comes in weak; you bringing yours warms the whole mine.", "Maria, que bom te ver. Aqui em cima a luz chega fraquinha; você trazendo a sua já esquenta a mina inteira."),
            new LocalizationEntry("dialogue.mountain_miner.greet_joaquim", "Joaquim! I heard you held back an avalanche with your shield. That's a tall tale, right? ...It isn't? This boy!", "Joaquim! Ouvi dizer que você segurou uma avalanche com o escudo. Conversa, né? ...Não é conversa? Esse menino!"),
            new LocalizationEntry("dialogue.mountain_miner.greet_icaro", "Ícaro, my boy! Did you bring the electric pickaxe you promised in that note you sent with Ammo? The stone ushabtis here would get quite a scare.", "Ícaro, rapaz! Trouxe a picareta elétrica que prometeu no recado que mandou pelo Ammo? Os ushabtis de pedra daqui iam levar um susto."),
            new LocalizationEntry("dialogue.mountain_miner.greet_lavine", "Lavine, you climbed the whole range? At your age I was scared of the mine ladder. You're braver than plenty of bearded miners.", "Lavine, você subiu a serra inteira? Eu, na sua idade, tinha medo até da escada da mina. Você é mais corajosa que muito mineiro barbado."),
            new LocalizationEntry("dialogue.mountain_miner.greet_any", "Hey, a visitor! Someone from the cousins' family climbs the range and old Mihr puts the tea on.", "Ê, visita! Gente da família dos primos sobe a serra e o velho Mihr já põe o chá no fogo."),
            new LocalizationEntry("dialogue.mountain_miner.menu", "Anything else to chat about?", "Mais alguma conversa?"),
            new LocalizationEntry("dialogue.mountain_miner.choice_q1", "Why is the mine closed?", "Por que a mina está parada?"),
            new LocalizationEntry("dialogue.mountain_miner.q1_offer", "The stones decided to walk! Stone ushabtis — the old guardians that were made to answer — come down the slope and crush the cart rails. Topple four of them and I'll pay you in gold and potions — a miner's word.", "As pedras resolveram andar! Ushabtis de pedra — os guardiões antigos que foram feitos pra responder — descem a encosta e esmagam os trilhos dos carrinhos. Derruba quatro deles e eu te pago em ouro e poção, palavra de mineiro."),
            new LocalizationEntry("dialogue.mountain_miner.choice_accept_special", "Stone against stone? Let me hold the line.", "Pedra contra pedra? Deixa que eu seguro a linha."),
            new LocalizationEntry("dialogue.mountain_miner.q1_accepted", "Hit the joints, that's where stone cracks. And don't charge ahead of everyone, alright? The mountain likes to punish the hasty.", "Bate nas juntas, que é onde a pedra racha. E não vai na frente de todo mundo, viu? A serra gosta de cobrar dos apressados."),
            new LocalizationEntry("dialogue.mountain_miner.q1_active", "I still hear ushabtis stomping up there. Just a few left, keep at it!", "Ainda escuto ushabti pisando lá em cima. Faltam poucos, coragem!"),
            new LocalizationEntry("dialogue.mountain_miner.choice_q2", "Can the mine reopen now?", "A mina já pode reabrir?"),
            new LocalizationEntry("dialogue.mountain_miner.q2_offer", "Almost! The rails are safe, but the deep mine pass is full of ushabtis. Topple six and the mine bell rings again. It hasn't rung in years.", "Quase! Os trilhos estão salvos, mas a passagem funda da mina está cheia de ushabti. Derruba seis e o sino da mina volta a tocar. Faz anos que ele não toca."),
            new LocalizationEntry("dialogue.mountain_miner.q2_accepted", "If the echo gets too loud, step out and breathe. None of your cousins want to dig you out from under a rock.", "Se o eco ficar alto demais, sai e respira. Nenhum primo seu quer te tirar de debaixo de pedra."),
            new LocalizationEntry("dialogue.mountain_miner.q2_active", "Six ushabtis in the deep pass. When the last one falls, you'll hear the bell.", "Seis ushabtis na passagem funda. Quando o último cair, você vai ouvir o sino."),
            new LocalizationEntry("dialogue.mountain_miner.all_done", "Hear that? It's the mine bell! I'll tell my grandkids about this: the five cousins who made the mountain sing again.", "Escutou? É o sino da mina! Vou contar essa pros meus netos: os cinco primos que fizeram a serra cantar de novo."),
            new LocalizationEntry("dialogue.mountain_miner.declined", "No problem. Stone has patience to spare.", "Sem problema. Pedra tem paciência de sobra."),
            new LocalizationEntry("dialogue.mountain_miner.boss", "Hahya, the Giant Warrior, commands the ushabtis from the ridge. Long ago he dreamed of ruin, was sorry, and became the range's guardian — the shadow made him forget. He hits hard and wide: whoever stands in front of him doesn't get up. Move sideways, strike from behind, and don't give up.", "Hahya, o Gigante Guerreiro, manda nos ushabtis lá da crista. Faz tempo ele sonhou com destruição, se arrependeu e virou guardião da serra — a sombra fez ele esquecer. Ele bate forte e bate largo: quem fica parado na frente dele não levanta. Anda de lado, ataca pelas costas e não desiste."),
            new LocalizationEntry("dialogue.mountain_miner.boss_special", "Joaquim, I know you'll want to stand in front to protect everyone. Against Hahya, protecting means knowing when to step aside. Shield up, quick feet, and come back in one piece so Maria doesn't pull my ear.", "Joaquim, eu sei que você vai querer ficar na frente pra proteger todo mundo. Contra o Hahya, proteger é saber sair do caminho na hora certa. Escudo erguido, pé ligeiro, e volta inteiro pra Maria não me puxar a orelha."),
            new LocalizationEntry("dialogue.mountain_miner.cleared", "Hahya has fallen — and remembered who he was! The whole range sighed with relief. Head down to the Threshold Caves carefully — down there is another world.", "O Hahya caiu — e lembrou quem era! A serra inteira suspirou de alívio. Desçam pras Grutas do Limiar com cuidado — lá embaixo é outro mundo."),

            // -- mountain_miner after the boss (greet_after_*, RegionNpcDialogues: region cleared) --
            new LocalizationEntry("dialogue.mountain_miner.greet_after_maithe", "Maithe! Since Hahya fell, the mountain wind has stopped shouting. Looks like it finally listened to you.", "Maithe! Depois que o Hahya caiu, o vento da serra parou de gritar. Parece que ele finalmente te escutou."),
            new LocalizationEntry("dialogue.mountain_miner.greet_after_maria", "Maria! They say Hahya lowered his sword and thanked you all. Turns out people who shout a lot really are just afraid.", "Maria! Dizem que o Hahya baixou a espada e agradeceu vocês. Quem grita muito é porque tá com medo, né?"),
            new LocalizationEntry("dialogue.mountain_miner.greet_after_joaquim", "Joaquim! I heard that against Hahya you stepped aside at just the right moment. See? That's protecting too. Maria won't be pulling my ear after all.", "Joaquim! Soube que contra o Hahya você saiu da frente na hora certa. Viu só? Proteger também é isso. A Maria não vai puxar minha orelha, não."),
            new LocalizationEntry("dialogue.mountain_miner.greet_after_icaro", "Ícaro! You found the weak spot in the joints of Hahya's armour, didn't you? I told you: hit the joints, that's where it cracks.", "Ícaro! Achou o ponto fraco nas juntas da armadura do Hahya, né? Eu bem que disse: bate nas juntas, que é onde racha."),
            new LocalizationEntry("dialogue.mountain_miner.greet_after_lavine", "Lavine! The girl who climbed the range and stood up to a giant. Not one bearded miner can say the same.", "Lavine! A menina que subiu a serra e encarou um gigante. Mineiro barbado nenhum pode dizer o mesmo."),
            new LocalizationEntry("dialogue.mountain_miner.greet_after_any", "Hahya remembered who he was and the range sighed with relief. Sit, the tea is brewing.", "O Hahya lembrou quem era e a serra suspirou de alívio. Senta, que o chá tá quentinho."),

            // ================= Cavernas (Grutas do Limiar) — Parthenos, a das Lamparinas =================
            new LocalizationEntry("quest.region_caves_dark_lamps.title", "Snuffed Lanterns", "Lamparinas Apagadas"),
            new LocalizationEntry("quest.region_caves_dark_lamps.description", "Bat swarms blow out Parthenos's lanterns, and in the dark no one can find the way out of the Threshold Caves.", "Enxames de morcegos apagam as lamparinas da Parthenos, e no escuro ninguém acha a saída das Grutas do Limiar."),
            new LocalizationEntry("quest.region_caves_dark_lamps.obj_scatter_bat_swarms", "Scatter threshold bat swarms", "Espantar enxames de morcegos do Limiar"),
            new LocalizationEntry("quest.region_caves_dark_lamps.journal", "Bats hate bright light and noise. Maria has plenty of light; Ícaro and Joaquim have plenty of noise.", "Morcego odeia luz forte e barulho. Luz, a Maria tem de sobra; barulho, o Ícaro e o Joaquim."),
            new LocalizationEntry("quest.region_caves_last_lantern.title", "The Last Lantern", "A Última Lamparina"),
            new LocalizationEntry("quest.region_caves_last_lantern.description", "In the deepest tunnel stands the oldest lantern in the caves, and the bats won't let anyone near it.", "No túnel mais fundo fica a lamparina mais antiga das grutas, e os morcegos não deixam ninguém chegar perto."),
            new LocalizationEntry("quest.region_caves_last_lantern.obj_light_the_deep_tunnel", "Clear the way to the last lantern", "Abrir caminho até a última lamparina"),
            new LocalizationEntry("quest.region_caves_last_lantern.journal", "Parthenos will light the last lantern in the names of the five of us. As long as it shines, the family won't get lost.", "A Parthenos vai acender a última lamparina com o nome de nós cinco. Enquanto ela brilhar, a família não se perde."),

            new LocalizationEntry("dialogue.caves_lampkeeper.name", "Parthenos of the Lamps", "Parthenos, a das Lamparinas"),
            new LocalizationEntry("dialogue.caves_lampkeeper.short_name", "Parthenos", "Parthenos"),
            new LocalizationEntry("dialogue.caves_lampkeeper.greet_maithe", "Maithe. Your hunter's eye is good in the dark, but here the dark looks back. Stay close to the light and to your own.", "Maithe. Seu olho de caçadora é bom no escuro, mas aqui o escuro olha de volta. Fica perto da luz e dos seus."),
            new LocalizationEntry("dialogue.caves_lampkeeper.greet_maria", "Maria! The lanterns flickered when you came in, as if they recognized your light. Stay a while; they like you.", "Maria! As lamparinas tremeram quando você entrou, como se reconhecessem a sua luz. Fica um pouco; elas gostam de você."),
            new LocalizationEntry("dialogue.caves_lampkeeper.greet_joaquim", "Joaquim, lower that shield — the ceiling's low down here and the echo is treacherous. Protectors can rest too, you know?", "Joaquim, abaixa esse escudo, que aqui embaixo o teto é baixo e o eco é traiçoeiro. Protetor também pode descansar, sabia?"),
            new LocalizationEntry("dialogue.caves_lampkeeper.greet_icaro", "Ícaro, the pocket lanterns you left with Master Mihr already saved two miners down here. I still prefer my oil, but... thank you.", "Ícaro, as lanternas de bolso que você deixou com o Mestre Mihr já salvaram dois mineiros aqui embaixo. Eu ainda prefiro meu óleo, mas... obrigada."),
            new LocalizationEntry("dialogue.caves_lampkeeper.greet_lavine", "Lavine. The shadows here grow quiet when you pass... Don't fear what you carry, child. In your hands, the night protects.", "Lavine. As sombras daqui se aquietam quando você passa... Não tenha medo do que você carrega, menina. Na sua mão, a noite protege."),
            new LocalizationEntry("dialogue.caves_lampkeeper.greet_any", "Another cousin came all the way down? Take a lantern; the path is long and cold. May your lamp never go out.", "Mais um dos primos desceu até aqui? Pega uma lamparina, que o caminho é longo e frio. Que a sua lâmpada não apague."),
            new LocalizationEntry("dialogue.caves_lampkeeper.menu", "Anything else before you head into the dark?", "Mais alguma coisa antes de seguir no escuro?"),
            new LocalizationEntry("dialogue.caves_lampkeeper.choice_q1", "Why are the lanterns out?", "Por que as lamparinas estão apagadas?"),
            new LocalizationEntry("dialogue.caves_lampkeeper.q1_offer", "The bat swarms. They beat their wings so hard they blow out my lanterns, and in the dark nobody finds the way out. Scatter six swarms and I'll give you the potions I keep for emergencies.", "Os enxames de morcegos. Batem as asas tão forte que apagam minhas lamparinas, e no escuro ninguém acha a saída. Espanta seis enxames e eu te dou as poções que guardo pra emergência."),
            new LocalizationEntry("dialogue.caves_lampkeeper.choice_accept_special", "I'll carry the light with me. You can count on us.", "Eu levo a luz comigo. Pode contar com a gente."),
            new LocalizationEntry("dialogue.caves_lampkeeper.q1_accepted", "Bats hate bright light and noise. Make both, and call your cousins if you need to.", "Morcego odeia luz forte e barulho. Faz os dois, e chama seus primos se precisar."),
            new LocalizationEntry("dialogue.caves_lampkeeper.q1_active", "There are still swarms flapping in the tunnels. Follow the screeching.", "Ainda tem enxame batendo asa nos túneis. Segue o chiado."),
            new LocalizationEntry("dialogue.caves_lampkeeper.choice_q2", "What about the deepest tunnel?", "E o túnel mais fundo?"),
            new LocalizationEntry("dialogue.caves_lampkeeper.q2_offer", "The entrance lanterns shine again, thanks to you. But in the deep tunnel there's the last lantern, the oldest one, and the bats won't let anyone near. Scatter eight more swarms and I'll light it for your family.", "As lamparinas da entrada voltaram a brilhar, graças a você. Mas no túnel fundo ainda tem a última lamparina, a mais antiga, e os morcegos não deixam ninguém chegar. Espanta mais oito enxames e eu acendo ela pra sua família."),
            new LocalizationEntry("dialogue.caves_lampkeeper.q2_accepted", "Go slowly. At the bottom of the caves, silence speaks louder than any scream.", "Vai devagar. No fundo da gruta, o silêncio fala mais alto que qualquer grito."),
            new LocalizationEntry("dialogue.caves_lampkeeper.q2_active", "Eight swarms in the deep tunnel. The last lantern is waiting for you.", "Oito enxames no túnel fundo. A última lamparina espera por vocês."),
            new LocalizationEntry("dialogue.caves_lampkeeper.all_done", "I lit the last lantern in the names of you five. As long as it shines, this family will never get lost in the dark.", "Acendi a última lamparina com o nome de vocês cinco. Enquanto ela brilhar, essa família nunca vai se perder no escuro."),
            new LocalizationEntry("dialogue.caves_lampkeeper.declined", "That's alright. The light waits for those who come back.", "Tudo bem. A luz espera quem volta."),
            new LocalizationEntry("dialogue.caves_lampkeeper.boss", "Tages, the Ancient Dweller, lives where no lantern reaches. He sees by sound: when he stops to listen, stay still. Then strike with everything. And don't hate him — they say he's afraid of the dark himself.", "Tages, o Habitante Ancestral, vive onde nenhuma lamparina chega. Ele enxerga pelo som: quando ele parar pra escutar, fica quieto. Depois ataca com tudo. E não tenha raiva dele — dizem que ele mesmo tem medo do escuro."),
            new LocalizationEntry("dialogue.caves_lampkeeper.boss_special", "Lavine, Tages will sense the night in you and try to frighten you. Don't let him. You're the youngest, but not the weakest: your shadow shields your family. Show him.", "Lavine, o Tages vai sentir a noite em você e tentar te assustar. Não deixa. Você é a caçula, mas não é a mais fraca: a sua sombra é escudo da sua família. Mostra pra ele."),
            new LocalizationEntry("dialogue.caves_lampkeeper.cleared", "Tages has gone quiet... The depths are silent — a good silence. You five brought light where it had never reached.", "O Tages se aquietou... O fundo da gruta está em silêncio, um silêncio bom. Vocês cinco levaram luz aonde ela nunca tinha chegado."),

            // -- caves_lampkeeper after the boss (greet_after_*, RegionNpcDialogues: region cleared) --
            new LocalizationEntry("dialogue.caves_lampkeeper.greet_after_maithe", "Maithe. Tages doesn't steal any more light... he even comes to borrow a lantern, can you believe it? Did you count your cousins? All there?", "Maithe. O Tages não rouba mais luz nenhuma... ele até vem pedir lamparina emprestada, acredita? Contou os primos? Estão todos?"),
            new LocalizationEntry("dialogue.caves_lampkeeper.greet_after_maria", "Maria! I heard you lit your light slowly for him. Since then the lanterns down here have never flickered again.", "Maria! Soube que você acendeu a sua luz devagarinho pra ele. Desde então as lamparinas daqui nunca mais tremeram."),
            new LocalizationEntry("dialogue.caves_lampkeeper.greet_after_joaquim", "Joaquim, you can lower that shield for good: down at the bottom there's only a neighbour who's afraid of the dark — with a brand-new lantern.", "Joaquim, pode baixar o escudo de vez: lá no fundo agora só mora um vizinho com medo do escuro — e com lamparina nova."),
            new LocalizationEntry("dialogue.caves_lampkeeper.greet_after_icaro", "Ícaro, Tages asked for one of your pocket lanterns. I said I'd ask you. An inventor has customers even at the bottom of a cave!", "Ícaro, o Tages pediu uma das suas lanternas de bolso. Eu disse que ia te perguntar. Inventor tem freguês até no fundo da gruta!"),
            new LocalizationEntry("dialogue.caves_lampkeeper.greet_after_lavine", "Lavine. You showed him a shadow can be soft too. Now the shadows down here greet you when you pass.", "Lavine. Você mostrou pra ele que a sombra também pode ser macia. Agora as sombras daqui te cumprimentam quando você passa."),
            new LocalizationEntry("dialogue.caves_lampkeeper.greet_after_any", "The depths are at peace and the light went home to the village. Take a lantern anyway — a habit of mine.", "O fundo da gruta está em paz, e a luz voltou pra vila. Pega uma lamparina mesmo assim — mania minha."),
        };

        public static void EnsureLoaded(LocalizationManager localization)
        {
            if (localization == null)
            {
                return;
            }

            localization.LoadEntries(All.Where(entry => !localization.HasKey(entry.Key)).ToList());
        }

        /// <summary>pt-BR text of <paramref name="key"/> without a manager (same no-manager fallback rule as the other helpers), or null.</summary>
        public static string GetFallback(string key)
        {
            LocalizationEntry entry = All.FirstOrDefault(e => e.Key == key);
            return entry?.PtBR;
        }
    }
}
